pub fn emit_seeds_declare(place: &mut EmitSeedsPlace, base: i64) {
    place.share = true;
    place.declaring = true;
    place.next = base;
    place.seen.clear();
}

pub fn emit_seeds_declare_fn(place: &mut EmitSeedsPlace, base: i64, groups: &[i64], within: &[i64], start: i64) {
    emit_seeds_declare(place, base);
    place.share = false;
    let mut names: Vec<String> = vec![];
    for _group in groups.iter() {
        let _group = nikaia_std::num::value(_group);
        names.push(String::from(""));
    }
    for at in 0..within.len() as i64 {
        let j = *nikaia_std::index::get(&within, (at) as usize);
        if j >= 0 { { let __nikaia_stored = format!("__S{}", j); nikaia_std::index::set(&mut names, nikaia_std::index::at(*nikaia_std::index::get(&groups, (at) as usize)), __nikaia_stored); } }
    }
    place.has_shape = true;
    place.groups = groups.to_owned();
    place.at = start;
    place.names = names;
}

pub fn emit_seeds_declare_type(place: &mut EmitSeedsPlace, base: i64) {
    emit_seeds_declare(place, base);
    place.share = false;
}

pub fn emit_seeds_finish(place: &mut EmitSeedsPlace, base: i64) -> i64 {
    let mut n = place.next - base;
    place.declaring = false;
    place.next = 0;
    if n < 0 { n = 0; }
    place.seen.clear();
    place.has_shape = false;
    place.groups = vec![];
    place.names = vec![];
    place.at = 0;
    n
}

pub fn emit_seeds_enter(place: &mut EmitSeedsPlace, target: &str, params: &[String]) {
    place.within_target = Some(target.to_string());
    place.within_params = params.to_owned();
}

pub fn emit_seeds_leave(place: &mut EmitSeedsPlace) {
    place.within_target = None;
    place.within_params = vec![];
}

pub fn emit_seeds_within(place: &EmitSeedsPlace) -> bool { place.within_target.is_some() }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmitSeedsShape {
    pub groups: Vec<i64>,
    pub within: Vec<i64>,
    pub start: i64,
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn emit_seeds_begin<H: EmitHost>(tables: &EmitSeedsTables, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, host: &H, written: &Item, owner_target: &Option<String>, owner_declared: bool) -> EmitSeedsBegin {
    match written {
        Item::Fn { name, args, ret_type, is_public, .. } => {
            let is_public = *is_public; let name = *name;
            let in_seeded_impl = emit_seeds_within(&walk.place);
            let has_owner = owner_target.is_some();
            let target: String = nikaia_std::index::or(match owner_target.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || "".into());
            let mut base: i64 = 0;
            if has_owner && in_seeded_impl { base = tables.arity(&target); }
            let has_name = name.is_some();
            let own_name: String = match name {
                Some(each) => emit_text(world, each),
                None => String::from(""),
            };
            let barrier = has_owner && owner_declared || !owner_declared && has_name && tables.is_fixed(&own_name);
            walk.floor = barrier;
            let mut seeded = !tables.is_empty() && !barrier && has_name && !owner_declared;
            if seeded { if is_public { seeded = emit_seeds_holds(tables, world.words, args, (ret_type).as_ref()); } else { seeded = emit_seeds_mentions(tables, world.words, args, (ret_type).as_ref()); } }
            if seeded {
                let mut shape: Option<EmitSeedsShape> = None;
                if is_public {
                    let key: String = if has_owner { format!("{}::{}", target, own_name) } else { own_name.to_string() };
                    shape = host.seeds_shape(&key);
                }
                match shape {
                    Some(ref s) => { emit_seeds_declare_fn(&mut walk.place, base, &s.groups, &s.within, s.start); },
                    None => { emit_seeds_declare(&mut walk.place, base); },
                }
            }
            return EmitSeedsBegin { base, seeded, in_seeded_impl };
        },
        _ => return EmitSeedsBegin { base: 0, seeded: false, in_seeded_impl: false },
    }
}

pub fn emit_seeds_end(walk: &mut EmitWalk, seeded: bool, base: i64) -> EmitSeedsEnd {
    walk.floor = false;
    let mut hidden: i64 = 0;
    if seeded { hidden = emit_seeds_finish(&mut walk.place, base); }
    EmitSeedsEnd { hidden, declared: emit_seeds_declared(base, hidden, false) }
}

pub fn emit_seeds_seeded(tables: &EmitSeedsTables, walk: &mut EmitWalk, trusted: bool, written: String) -> String {
    let floor = walk.floor;
    let mut text = written;
    if floor { text = text.replace("TrustedMap", "HashMap").replace("TrustedSet", "HashSet"); }
    if tables.is_empty() { return text; }
    emit_seeds_write(&text, &mut walk.place, trusted && !floor, tables)
}

pub(crate) fn emit_seeds_position(place: &mut EmitSeedsPlace) -> String {
    if !place.has_shape { return String::from(""); }
    let me = place.at;
    place.at += 1;
    if me >= place.groups.len() as i64 { return String::from(""); }
    let group = *nikaia_std::index::get(&place.groups, nikaia_std::index::at(me));
    if *nikaia_std::index::get(&place.names, nikaia_std::index::at(group)) == "" {
        { let __nikaia_stored = format!("__S{}", place.next); nikaia_std::index::set(&mut place.names, nikaia_std::index::at(group), __nikaia_stored); }
        place.next += 1;
    }
    (*nikaia_std::index::get(&place.names, nikaia_std::index::at(group))).to_string()
}

pub(crate) fn emit_seeds_own(place: &mut EmitSeedsPlace) -> String {
    let own = emit_seeds_position(place);
    if own != "" { return own; }
    let fresh = format!("__S{}", place.next);
    place.next += 1;
    fresh
}

pub(crate) fn emit_seeds_last_start(c: &[scalar]) -> i64 {
    let mut from: i64 = 0;
    let mut at: i64 = 0;
    while ((at + 1) as usize) < c.len() {
        if *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' {
            from = at + 2;
            at += 2;
        } else { at += 1; }
    }
    from
}

pub(crate) fn emit_seeds_between(c: &[scalar], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

pub fn emit_seeds_last(name: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
    emit_seeds_between(&c, emit_seeds_last_start(&c), c.len() as i64)
}

pub fn emit_seeds_is_map(name: &str) -> bool {
    let l = emit_seeds_last(name);
    l == "HashMap" || l == "HashSet" || l == "TrustedMap" || l == "TrustedSet"
}

pub(crate) fn emit_seeds_renamed(path: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(path.chars());
    let from = emit_seeds_last_start(&c);
    let head = emit_seeds_between(&c, 0, from);
    let word = emit_seeds_between(&c, from, c.len() as i64);
    let name = match &*word {
        "TrustedMap" => "HashMap",
        "TrustedSet" => "HashSet",
        other => other,
    };
    format!("{}{}", head, name)
}

pub(crate) fn emit_seeds_within_hit(place: &EmitSeedsPlace, path: &str) -> bool {
    let target = nikaia_std::index::or(match place.within_target.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || "".into());
    place.within_target.is_some() && emit_seeds_last(path) == target
}

pub(crate) fn emit_seeds_closing(c: &[scalar], open: i64) -> i64 {
    let mut depth = 0;
    let mut at = open;
    while at < c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '<' { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '-' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '>' { at += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '>' {
            depth -= 1;
            if depth == 0 { return at + 1; }
        }
        at += 1;
    }
    c.len() as i64
}

pub(crate) fn emit_seeds_put(run: &mut EmitSeedsRun, text: &str) { for ch in text.chars() { run.out.push(ch); } }

pub fn emit_seeds_write(text: &str, place: &mut EmitSeedsPlace, fast: bool, tables: &EmitSeedsTables) -> String {
    let mut run = EmitSeedsRun { c: nikaia_std::list::chars(text.chars()), at: 0, out: vec![] };
    emit_seeds_run(&mut run, place, fast, tables, false);
    let mut out: String = String::from("");
    for ch in run.out.iter() {
        let ch = nikaia_std::num::value(ch);
        out.push(ch);
    }
    out
}

pub(crate) fn emit_seeds_run(run: &mut EmitSeedsRun, place: &mut EmitSeedsPlace, fast: bool, tables: &EmitSeedsTables, inside: bool) {
    while run.at < run.c.len() as i64 {
        let ch = *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at));
        if inside && ch == '>' { return; }
        if ch == '-' && run.at + 1 < run.c.len() as i64 && *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at + 1)) == '>' {
            run.out.push('-');
            run.out.push('>');
            run.at += 2;
            continue;
        }
        if ch == '\'' {
            run.out.push(ch);
            run.at += 1;
            while run.at < run.c.len() as i64 && ((*nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at))).is_alphanumeric() || *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at)) == '_') {
                run.out.push(*nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at)));
                run.at += 1;
            }
            continue;
        }
        if ch.is_alphanumeric() || ch == '_' {
            let start = run.at;
            let mut more = true;
            while more && run.at < run.c.len() as i64 {
                let b = *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at));
                if b.is_alphanumeric() || b == '_' { run.at += 1; } else if b == ':' && run.at + 2 < run.c.len() as i64 && *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at + 1)) == ':' && ((*nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at + 2))).is_alphanumeric() || *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at + 2)) == '_') { run.at += 2; } else { more = false; }
            }
            let path = emit_seeds_between(&run.c, start, run.at);
            emit_seeds_mention(run, &path, place, fast, tables);
            continue;
        }
        run.out.push(ch);
        run.at += 1;
    }
}

pub(crate) fn emit_seeds_mention(run: &mut EmitSeedsRun, path: &str, place: &mut EmitSeedsPlace, fast: bool, tables: &EmitSeedsTables) {
    let has_args = run.at < run.c.len() as i64 && *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at)) == '<';
    let is_m = emit_seeds_is_map(path);
    let map = is_m && has_args;
    let mut k: i64 = 0;
    if !is_m { k = tables.arity(path); }
    if !map && k == 0 {
        emit_seeds_put(run, path);
        return;
    }
    let after = run.at;
    let mut end = after;
    if has_args { end = emit_seeds_closing(&run.c, after); }
    let hit = emit_seeds_within_hit(&place, path);
    let key = format!("{}{}", emit_seeds_last(&emit_seeds_renamed(path)), emit_seeds_between(&run.c, after, end));
    if place.declaring && place.share && !hit {
        for seen in place.seen.iter() {
            if seen.key == key {
                emit_seeds_put(run, &seen.written);
                run.at = end;
                return;
            }
        }
    }
    let before = run.out.len() as i64;
    let mut added: Vec<String> = vec![];
    let mut name = path.to_string();
    if map {
        if place.declaring {
            added.push(emit_seeds_own(place));
            name = emit_seeds_renamed(path);
        }
    } else if hit {
        added = place.within_params.to_owned();
        if place.has_shape { for _step in 0..k { let skipped = emit_seeds_position(place); } }
    } else if place.declaring && place.has_shape { for _step in 0..k { added.push(emit_seeds_own(place)); } } else if place.declaring {
        for step in 0..k { added.push(format!("__S{}", place.next + step)); }
        place.next += k;
    } else { for _step in 0..k { if fast { added.push(String::from("nikaia_std::hash::Fast")); } else { added.push(String::from("nikaia_std::hash::Keyed")); } } }
    emit_seeds_put(run, &name);
    if has_args {
        run.out.push('<');
        run.at += 1;
        emit_seeds_run(run, place, fast, tables, true);
        for a in added.iter() {
            emit_seeds_put(run, ", ");
            emit_seeds_put(run, a);
        }
        if run.at < run.c.len() as i64 && *nikaia_std::index::get(&run.c, nikaia_std::index::at(run.at)) == '>' {
            run.out.push('>');
            run.at += 1;
        }
    } else if !added.is_empty() {
        run.out.push('<');
        let mut first = true;
        for a in added.iter() {
            if !first { emit_seeds_put(run, ", "); }
            first = false;
            emit_seeds_put(run, a);
        }
        run.out.push('>');
    }
    if place.declaring && place.share && !hit {
        let mut written: String = String::from("");
        for at in before..run.out.len() as i64 { written.push(*nikaia_std::index::get(&run.out, nikaia_std::index::at(at))); }
        place.seen.push(EmitSeedsSeen { key, written });
    }
}

